UPDATE pms_product SET slug='cbjj-s9-pro-pneumatic-tire-electric-scooter', name='{"en":"CBJJ S9 Pro Pneumatic Tire Electric Scooter","zh":"CBJJ S9 Pro 充气轮胎电动滑板车"}', subtitle='{"en":"A foldable city scooter with 10-inch pneumatic tires.","zh":"配备 10 英寸充气轮胎的折叠式城市滑板车。"}', description='{"en":"<p>A foldable city scooter with 10-inch pneumatic tires.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Check tire pressure, the folding latch and braking response before each ride. The 350W standard model suits short urban trips; select a variant for its own price and stock.</p>","zh":"<p>配备 10 英寸充气轮胎的折叠式城市滑板车。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。每次骑行前检查胎压、折叠锁扣和制动响应。基础版为 350W 城市车型，请按所选 SKU 核对价格与库存。</p>"}', pic='/cbjj/products/1/main.png', images='["/cbjj/products/1/main.png","/cbjj/products/1/detail.png","/cbjj/products/1/scene.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Battery","value":"36V 7.5Ah"},{"label":"Motor","value":"350W"},{"label":"Range","value":"19 Miles"},{"label":"Top Speed","value":"19 MPH"},{"label":"Tires","value":"10 inch pneumatic"}],"zh":[{"label":"电池","value":"36V 7.5Ah"},{"label":"电机","value":"350W"},{"label":"续航（估算）","value":"19 英里"},{"label":"最高速度（估算）","value":"19 英里/小时"},{"label":"轮胎","value":"10 英寸充气轮胎"}]}', specs='{"en":[{"label":"Battery","value":"36V 7.5Ah","icon":"BatteryIcon"},{"label":"Motor","value":"350W","icon":"ZapIcon"},{"label":"Range","value":"19 Miles","icon":"ZapIcon"},{"label":"Top Speed","value":"19 MPH","icon":"ZapIcon"}],"zh":[{"label":"电池","value":"36V 7.5Ah","icon":"BatteryIcon"},{"label":"电机","value":"350W","icon":"ZapIcon"},{"label":"续航（估算）","value":"19 英里","icon":"ZapIcon"},{"label":"最高速度（估算）","value":"19 英里/小时","icon":"ZapIcon"}]}', quick_know='{"en":["A foldable city scooter with 10-inch pneumatic tires.","Check tire pressure, the folding latch and braking response before each ride. The 350W standard model suits short urban trips; select a variant for its own price and stock.","Only in-stock variants are sold."],"zh":["配备 10 英寸充气轮胎的折叠式城市滑板车。","每次骑行前检查胎压、折叠锁扣和制动响应。基础版为 350W 城市车型，请按所选 SKU 核对价格与库存。","仅销售有库存的所选版本。"]}', box_items='{"en":["Scooter body","Charger","Toolkit","Manual","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["滑板车主体","适配充电器","工具包","使用说明书","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Check tire pressure, the folding latch and braking response before each ride. The 350W standard model suits short urban trips; select a variant for its own price and stock."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"每次骑行前检查胎压、折叠锁扣和制动响应。基础版为 350W 城市车型，请按所选 SKU 核对价格与库存。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[{"code":"warranty-1y","name":"1-Year Extended Limited Warranty","description":"Adds 1 year(s) after the included one-year limited warranty. The same defect coverage and exclusions apply; statutory rights remain unaffected.","price":79.99,"compareAtPrice":99.99,"image":"/cbjj/hero/hero.png"},{"code":"cable-lock","name":"CBJJ Cable Lock","description":"Steel cable parking lock. Confirm mounting and reach before purchase.","price":29.99,"compareAtPrice":39.99,"image":"/cbjj/products/7/main.png"}],"zh":[{"code":"warranty-1y","name":"1 年延长有限保修","description":"在随附的一年有限保修结束后延长 1 年，适用相同的缺陷保障和除外条款，不影响法定权利。","price":79.99,"compareAtPrice":99.99,"image":"/cbjj/hero/hero.png"},{"code":"cable-lock","name":"CBJJ 钢缆锁","description":"用于停车固定的钢缆锁，购买前请核对固定方式及长度适配。","price":29.99,"compareAtPrice":39.99,"image":"/cbjj/products/7/main.png"}]}' WHERE id=1;

