UPDATE pms_product SET slug='s-nova-pro-commuting-electric-scooter', name='{"en":"CBJJ S Nova Pro Commuting Electric Scooter","zh":"CBJJ S Nova Pro 通勤电动滑板车"}', subtitle='{"en":"A commuter scooter with a 1000W catalog motor and 48V 13Ah battery.","zh":"现有商品参数标注 1000W 电机、48V 13Ah 电池的通勤滑板车。"}', description='{"en":"<p>A commuter scooter with a 1000W catalog motor and 48V 13Ah battery.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Check the battery charge, folding mechanism and brakes before departure. Range and speed are catalog estimates, affected by rider weight, temperature and terrain.</p>","zh":"<p>现有商品参数标注 1000W 电机、48V 13Ah 电池的通勤滑板车。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。出发前检查电量、折叠机构和刹车。续航与速度为现有商品资料的估算值，受骑行者重量、温度及地形影响。</p>"}', pic='/cbjj/products/2/main.png', images='["/cbjj/products/2/main.png","/cbjj/products/2/detail.png","/cbjj/products/2/scene.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Motor","value":"1000W"},{"label":"Range","value":"38 Miles"},{"label":"Top Speed","value":"28 MPH"},{"label":"Battery","value":"48V 13Ah"}],"zh":[{"label":"电机","value":"1000W"},{"label":"续航（估算）","value":"38 英里"},{"label":"最高速度（估算）","value":"28 英里/小时"},{"label":"电池","value":"48V 13Ah"}]}', specs='{"en":[{"label":"Motor","value":"1000W","icon":"ZapIcon"},{"label":"Range","value":"38 Miles","icon":"ZapIcon"},{"label":"Top Speed","value":"28 MPH","icon":"ZapIcon"},{"label":"Battery","value":"48V 13Ah","icon":"BatteryIcon"}],"zh":[{"label":"电机","value":"1000W","icon":"ZapIcon"},{"label":"续航（估算）","value":"38 英里","icon":"ZapIcon"},{"label":"最高速度（估算）","value":"28 英里/小时","icon":"ZapIcon"},{"label":"电池","value":"48V 13Ah","icon":"BatteryIcon"}]}', quick_know='{"en":["A commuter scooter with a 1000W catalog motor and 48V 13Ah battery.","Check the battery charge, folding mechanism and brakes before departure. Range and speed are catalog estimates, affected by rider weight, temperature and terrain.","Only in-stock variants are sold."],"zh":["现有商品参数标注 1000W 电机、48V 13Ah 电池的通勤滑板车。","出发前检查电量、折叠机构和刹车。续航与速度为现有商品资料的估算值，受骑行者重量、温度及地形影响。","仅销售有库存的所选版本。"]}', box_items='{"en":["Scooter body","Charger","Toolkit","Manual","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["滑板车主体","适配充电器","工具包","使用说明书","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Check the battery charge, folding mechanism and brakes before departure. Range and speed are catalog estimates, affected by rider weight, temperature and terrain."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"出发前检查电量、折叠机构和刹车。续航与速度为现有商品资料的估算值，受骑行者重量、温度及地形影响。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[{"code":"warranty-2y","name":"2-Year Extended Limited Warranty","description":"Adds 2 year(s) after the included one-year limited warranty. The same defect coverage and exclusions apply; statutory rights remain unaffected.","price":99.99,"compareAtPrice":129.99,"image":"/cbjj/hero/hero.png"}],"zh":[{"code":"warranty-2y","name":"2 年延长有限保修","description":"在随附的一年有限保修结束后延长 2 年，适用相同的缺陷保障和除外条款，不影响法定权利。","price":99.99,"compareAtPrice":129.99,"image":"/cbjj/hero/hero.png"}]}' WHERE id=2;

