UPDATE pms_product SET slug='cbjj-u8-electric-bike-for-adults', name='{"en":"CBJJ U8 Electric Bike for Adults","zh":"CBJJ U8 成人电动自行车"}', subtitle='{"en":"A step-through electric bike for adult everyday riding.","zh":"采用低跨点车架，适合成人日常骑行。"}', description='{"en":"<p>A step-through electric bike for adult everyday riding.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Confirm frame fit and saddle position, and check both disc brakes before riding. Charge using the supplied compatible charger and keep electrical connections dry.</p>","zh":"<p>采用低跨点车架，适合成人日常骑行。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。先确认车架与身高适配、调整坐垫，并检查前后碟刹。使用随附的适配充电器，保持电气接口干燥。</p>"}', pic='/cbjj/products/3/main.png', images='["/cbjj/products/3/main.png","/cbjj/products/3/detail.png","/cbjj/products/3/scene.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Battery","value":"48V 15Ah"},{"label":"Motor","value":"750W"},{"label":"Frame","value":"Step-through aluminum"},{"label":"Brakes","value":"Mechanical disc"}],"zh":[{"label":"电池","value":"48V 15Ah"},{"label":"电机","value":"750W"},{"label":"车架","value":"低跨点铝合金车架"},{"label":"刹车","value":"机械碟刹"}]}', specs='{"en":[{"label":"Battery","value":"48V 15Ah","icon":"BatteryIcon"},{"label":"Motor","value":"750W","icon":"ZapIcon"},{"label":"Frame","value":"Step-through aluminum","icon":"ZapIcon"},{"label":"Brakes","value":"Mechanical disc","icon":"ZapIcon"}],"zh":[{"label":"电池","value":"48V 15Ah","icon":"BatteryIcon"},{"label":"电机","value":"750W","icon":"ZapIcon"},{"label":"车架","value":"低跨点铝合金车架","icon":"ZapIcon"},{"label":"刹车","value":"机械碟刹","icon":"ZapIcon"}]}', quick_know='{"en":["A step-through electric bike for adult everyday riding.","Confirm frame fit and saddle position, and check both disc brakes before riding. Charge using the supplied compatible charger and keep electrical connections dry.","Only in-stock variants are sold."],"zh":["采用低跨点车架，适合成人日常骑行。","先确认车架与身高适配、调整坐垫，并检查前后碟刹。使用随附的适配充电器，保持电气接口干燥。","仅销售有库存的所选版本。"]}', box_items='{"en":["Bike frame","Battery","Charger","Pedals","Toolkit","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["车架主体","电池","适配充电器","脚踏","工具包","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Confirm frame fit and saddle position, and check both disc brakes before riding. Charge using the supplied compatible charger and keep electrical connections dry."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"先确认车架与身高适配、调整坐垫，并检查前后碟刹。使用随附的适配充电器，保持电气接口干燥。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[{"code":"rear-basket","name":"CBJJ Rear Basket","description":"Add extra storage for groceries or gear.","price":49.99,"compareAtPrice":69.99,"image":"/cbjj/hero/hero.png"}],"zh":[{"code":"rear-basket","name":"CBJJ Rear Basket","description":"请核对所选配件的适配条件。","price":49.99,"compareAtPrice":69.99,"image":"/cbjj/hero/hero.png"}]}' WHERE id=3;

