UPDATE pms_product SET slug='cbjj-v8-electric-skateboard-with-remote', name='{"en":"CBJJ V8 Electric Skateboard with Remote","zh":"CBJJ V8 遥控电动滑板"}', subtitle='{"en":"An electric longboard supplied with a wireless handheld remote.","zh":"搭配无线手持遥控器的电动长板。"}', description='{"en":"<p>An electric longboard supplied with a wireless handheld remote.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Practice remote operation and braking at low speed on a dry, level, closed area. Wear a properly fitted helmet; do not ride in standing water.</p>","zh":"<p>搭配无线手持遥控器的电动长板。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。先在干燥、平整、封闭场地低速练习遥控操作和制动。佩戴合适头盔，不在积水中滑行。</p>"}', pic='/cbjj/products/5/main.png', images='["/cbjj/products/5/main.png","/cbjj/products/5/detail.png","/cbjj/products/5/scene.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Battery","value":"36V 4Ah"},{"label":"Motor","value":"700W"},{"label":"Deck","value":"8-layer maple"},{"label":"Remote","value":"2.4G wireless"}],"zh":[{"label":"电池","value":"36V 4Ah"},{"label":"电机","value":"700W"},{"label":"板面","value":"8 层枫木"},{"label":"遥控器","value":"2.4G 无线遥控"}]}', specs='{"en":[{"label":"Battery","value":"36V 4Ah","icon":"BatteryIcon"},{"label":"Motor","value":"700W","icon":"ZapIcon"},{"label":"Deck","value":"8-layer maple","icon":"ZapIcon"},{"label":"Remote","value":"2.4G wireless","icon":"ZapIcon"}],"zh":[{"label":"电池","value":"36V 4Ah","icon":"BatteryIcon"},{"label":"电机","value":"700W","icon":"ZapIcon"},{"label":"板面","value":"8 层枫木","icon":"ZapIcon"},{"label":"遥控器","value":"2.4G 无线遥控","icon":"ZapIcon"}]}', quick_know='{"en":["An electric longboard supplied with a wireless handheld remote.","Practice remote operation and braking at low speed on a dry, level, closed area. Wear a properly fitted helmet; do not ride in standing water.","Only in-stock variants are sold."],"zh":["搭配无线手持遥控器的电动长板。","先在干燥、平整、封闭场地低速练习遥控操作和制动。佩戴合适头盔，不在积水中滑行。","仅销售有库存的所选版本。"]}', box_items='{"en":["Board","Remote","Charger","Toolkit","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["滑板主体","遥控器","适配充电器","工具包","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Practice remote operation and braking at low speed on a dry, level, closed area. Wear a properly fitted helmet; do not ride in standing water."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"先在干燥、平整、封闭场地低速练习遥控操作和制动。佩戴合适头盔，不在积水中滑行。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[{"code":"wrist-guard","name":"CBJJ Protective Wrist Guard Set","description":"Extra confidence for new riders.","price":19.99,"compareAtPrice":29.99,"image":"/cbjj/hero/hero.png"}],"zh":[{"code":"wrist-guard","name":"CBJJ Protective Wrist Guard Set","description":"请核对所选配件的适配条件。","price":19.99,"compareAtPrice":29.99,"image":"/cbjj/hero/hero.png"}]}' WHERE id=5;

