UPDATE pms_product SET slug='cbjj-v10-off-road-electric-skateboard', name='{"en":"CBJJ V10 Off Road Electric Skateboard","zh":"CBJJ V10 越野电动滑板"}', subtitle='{"en":"An all-terrain electric board with a wide composite deck.","zh":"采用宽复合板面的全地形电动滑板。"}', description='{"en":"<p>An all-terrain electric board with a wide composite deck.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Inspect the wheels, trucks and remote charge before use. Start with a smooth, dry training surface; rough surfaces can reduce traction and range.</p>","zh":"<p>采用宽复合板面的全地形电动滑板。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。使用前检查车轮、桥架及遥控器电量。先在平整干燥路面练习，复杂路面可能降低抓地力和续航。</p>"}', pic='/cbjj/products/6/main.png', images='["/cbjj/products/6/main.png","/cbjj/products/6/detail.png","/cbjj/products/6/scene.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Battery","value":"36V 7Ah"},{"label":"Motor","value":"1200W"},{"label":"Wheel","value":"All-terrain"},{"label":"Deck","value":"Wide maple composite"}],"zh":[{"label":"电池","value":"36V 7Ah"},{"label":"电机","value":"1200W"},{"label":"车轮","value":"全地形车轮"},{"label":"板面","value":"宽枫木复合板"}]}', specs='{"en":[{"label":"Battery","value":"36V 7Ah","icon":"BatteryIcon"},{"label":"Motor","value":"1200W","icon":"ZapIcon"},{"label":"Wheel","value":"All-terrain","icon":"ZapIcon"},{"label":"Deck","value":"Wide maple composite","icon":"ZapIcon"}],"zh":[{"label":"电池","value":"36V 7Ah","icon":"BatteryIcon"},{"label":"电机","value":"1200W","icon":"ZapIcon"},{"label":"车轮","value":"全地形车轮","icon":"ZapIcon"},{"label":"板面","value":"宽枫木复合板","icon":"ZapIcon"}]}', quick_know='{"en":["An all-terrain electric board with a wide composite deck.","Inspect the wheels, trucks and remote charge before use. Start with a smooth, dry training surface; rough surfaces can reduce traction and range.","Only in-stock variants are sold."],"zh":["采用宽复合板面的全地形电动滑板。","使用前检查车轮、桥架及遥控器电量。先在平整干燥路面练习，复杂路面可能降低抓地力和续航。","仅销售有库存的所选版本。"]}', box_items='{"en":["Board","Remote","Charger","Toolkit","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["滑板主体","遥控器","适配充电器","工具包","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Inspect the wheels, trucks and remote charge before use. Start with a smooth, dry training surface; rough surfaces can reduce traction and range."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"使用前检查车轮、桥架及遥控器电量。先在平整干燥路面练习，复杂路面可能降低抓地力和续航。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[{"code":"helmet-addon","name":"CBJJ Riding Helmet","description":"Adult helmet. Confirm size and fit before purchase.","price":39.99,"compareAtPrice":59.99,"image":"/cbjj/products/8/main.png"}],"zh":[{"code":"helmet-addon","name":"CBJJ 骑行头盔","description":"成人头盔，购买前请确认尺寸及佩戴适配。","price":39.99,"compareAtPrice":59.99,"image":"/cbjj/products/8/main.png"}]}' WHERE id=6;

