UPDATE pms_product SET slug='electric-bike-cable-lock', name='{"en":"CBJJ Electric Bike Cable Lock","zh":"CBJJ 电动自行车钢缆锁"}', subtitle='{"en":"A protective-coated steel cable lock for everyday parking.","zh":"带保护包覆层的钢缆锁，适合日常停车固定。"}', description='{"en":"<p>A protective-coated steel cable lock for everyday parking.</p><p>Secure the vehicle frame to a fixed anchor, and keep the keys separate from the lock. A cable lock is a parking deterrent and does not guarantee theft prevention.</p>","zh":"<p>带保护包覆层的钢缆锁，适合日常停车固定。</p><p>将车辆主车架锁在固定锚点上，钥匙与锁分开保管。钢缆锁用于提升停车防护，不保证杜绝盗窃。</p>"}', pic='/cbjj/products/7/main.png', images='["/cbjj/products/7/main.png","/cbjj/products/7/detail.png","/cbjj/products/7/scene.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Length","value":"120 cm"},{"label":"Core","value":"Steel cable"}],"zh":[{"label":"长度","value":"120 cm"},{"label":"锁芯结构","value":"钢缆"}]}', specs='{"en":[{"label":"Length","value":"120 cm","icon":"ZapIcon"},{"label":"Core","value":"Steel cable","icon":"ZapIcon"}],"zh":[{"label":"长度","value":"120 cm","icon":"ZapIcon"},{"label":"锁芯结构","value":"钢缆","icon":"ZapIcon"}]}', quick_know='{"en":["A protective-coated steel cable lock for everyday parking.","Secure the vehicle frame to a fixed anchor, and keep the keys separate from the lock. A cable lock is a parking deterrent and does not guarantee theft prevention.","Only in-stock variants are sold."],"zh":["带保护包覆层的钢缆锁，适合日常停车固定。","将车辆主车架锁在固定锚点上，钥匙与锁分开保管。钢缆锁用于提升停车防护，不保证杜绝盗窃。","仅销售有库存的所选版本。"]}', box_items='{"en":["Cable lock","Keys","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["钢缆锁","钥匙","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Secure the vehicle frame to a fixed anchor, and keep the keys separate from the lock. A cable lock is a parking deterrent and does not guarantee theft prevention."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"将车辆主车架锁在固定锚点上，钥匙与锁分开保管。钢缆锁用于提升停车防护，不保证杜绝盗窃。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[],"zh":[]}' WHERE id=7;

