UPDATE pms_product SET slug='adult-riding-helmet', name='{"en":"CBJJ Adult Riding Helmet","zh":"CBJJ 成人骑行头盔"}', subtitle='{"en":"A ventilated adult helmet with a PC shell and EPS liner.","zh":"采用 PC 外壳与 EPS 内衬的透气成人头盔。"}', description='{"en":"<p>A ventilated adult helmet with a PC shell and EPS liner.</p><p>Choose M or L using the selected variant, and confirm a snug fit before use. Replace a helmet after a significant impact, even when damage is not visible.</p>","zh":"<p>采用 PC 外壳与 EPS 内衬的透气成人头盔。</p><p>按所选版本选择 M 或 L，并确认佩戴稳固。头盔受到明显撞击后应更换，即使外观没有可见损伤。</p>"}', pic='/cbjj/products/8/main.png', images='["/cbjj/products/8/main.png","/cbjj/products/8/detail.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Weight","value":"320 g"},{"label":"Shell","value":"PC + EPS"}],"zh":[{"label":"重量","value":"320 g"},{"label":"外壳/内衬","value":"PC + EPS"}]}', specs='{"en":[{"label":"Weight","value":"320 g","icon":"ZapIcon"},{"label":"Shell","value":"PC + EPS","icon":"ZapIcon"}],"zh":[{"label":"重量","value":"320 g","icon":"ZapIcon"},{"label":"外壳/内衬","value":"PC + EPS","icon":"ZapIcon"}]}', quick_know='{"en":["A ventilated adult helmet with a PC shell and EPS liner.","Choose M or L using the selected variant, and confirm a snug fit before use. Replace a helmet after a significant impact, even when damage is not visible.","Only in-stock variants are sold."],"zh":["采用 PC 外壳与 EPS 内衬的透气成人头盔。","按所选版本选择 M 或 L，并确认佩戴稳固。头盔受到明显撞击后应更换，即使外观没有可见损伤。","仅销售有库存的所选版本。"]}', box_items='{"en":["Helmet","Padding set","Manual","Visor accessory when the Visor Kit is selected.","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["头盔","衬垫","使用说明书","选择 Visor Kit 时包含遮阳配件。","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Choose M or L using the selected variant, and confirm a snug fit before use. Replace a helmet after a significant impact, even when damage is not visible."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"按所选版本选择 M 或 L，并确认佩戴稳固。头盔受到明显撞击后应更换，即使外观没有可见损伤。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[],"zh":[]}' WHERE id=8;

