UPDATE pms_product SET slug='cbjj-u1-folding-electric-scooter', name='{"en":"CBJJ U1 Folding Electric Scooter","zh":"CBJJ U1 折叠电动滑板车"}', subtitle='{"en":"A folding commuter scooter with a 48V 10Ah catalog battery.","zh":"现有商品参数标注 48V 10Ah 电池的折叠通勤滑板车。"}', description='{"en":"<p>A folding commuter scooter with a 48V 10Ah catalog battery.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Check the folding latch, battery charge and brakes before riding. Fold only after the scooter has stopped; keep fingers away from moving joints.</p>","zh":"<p>现有商品参数标注 48V 10Ah 电池的折叠通勤滑板车。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。骑行前检查折叠锁扣、电量和刹车。完全停稳后再折叠，手指远离活动关节。</p>"}', pic='/cbjj/products/9/main.png', images='["/cbjj/products/9/main.png","/cbjj/products/9/detail.png","/cbjj/products/9/scene.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Motor","value":"500W"},{"label":"Range","value":"25 Miles"},{"label":"Top Speed","value":"21 MPH"},{"label":"Battery","value":"48V 10Ah"},{"label":"Weight","value":"44 lbs"}],"zh":[{"label":"电机","value":"500W"},{"label":"续航（估算）","value":"25 英里"},{"label":"最高速度（估算）","value":"21 英里/小时"},{"label":"电池","value":"48V 10Ah"},{"label":"重量","value":"44 磅"}]}', specs='{"en":[{"label":"Motor","value":"500W","icon":"ZapIcon"},{"label":"Range","value":"25 Miles","icon":"ZapIcon"},{"label":"Top Speed","value":"21 MPH","icon":"ZapIcon"},{"label":"Battery","value":"48V 10Ah","icon":"BatteryIcon"}],"zh":[{"label":"电机","value":"500W","icon":"ZapIcon"},{"label":"续航（估算）","value":"25 英里","icon":"ZapIcon"},{"label":"最高速度（估算）","value":"21 英里/小时","icon":"ZapIcon"},{"label":"电池","value":"48V 10Ah","icon":"BatteryIcon"}]}', quick_know='{"en":["A folding commuter scooter with a 48V 10Ah catalog battery.","Check the folding latch, battery charge and brakes before riding. Fold only after the scooter has stopped; keep fingers away from moving joints.","Only in-stock variants are sold."],"zh":["现有商品参数标注 48V 10Ah 电池的折叠通勤滑板车。","骑行前检查折叠锁扣、电量和刹车。完全停稳后再折叠，手指远离活动关节。","仅销售有库存的所选版本。"]}', box_items='{"en":["Scooter body","Charger","Toolkit","User manual","Other kit contents and version differences are not specified in the current catalog; confirm them with support before purchase."],"zh":["滑板车主体","适配充电器","工具包","使用说明书","现有资料未列明其他套装附件及版本差异，请在购买前联系客服确认。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Check the folding latch, battery charge and brakes before riding. Fold only after the scooter has stopped; keep fingers away from moving joints."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"骑行前检查折叠锁扣、电量和刹车。完全停稳后再折叠，手指远离活动关节。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[{"code":"helmet-kit","name":"CBJJ Riding Helmet","description":"Adult helmet. Confirm size and fit before purchase.","price":39.99,"compareAtPrice":49.99,"image":"/cbjj/products/8/main.png"}],"zh":[{"code":"helmet-kit","name":"CBJJ 骑行头盔","description":"成人头盔，购买前请确认尺寸及佩戴适配。","price":39.99,"compareAtPrice":49.99,"image":"/cbjj/products/8/main.png"}]}' WHERE id=9;

