UPDATE pms_product SET slug='cbjj-u2-electric-cruiser-bike', name='{"en":"CBJJ U2 Electric Cruiser Bike","zh":"CBJJ U2 休闲电动自行车"}', subtitle='{"en":"A step-through cruiser bike available in black or white.","zh":"提供黑、白两款的低跨点休闲电动自行车。"}', description='{"en":"<p>A step-through cruiser bike available in black or white.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Adjust the saddle and check the brakes, tires and battery attachment before riding. The listed gift is a bike lock; the included one-year warranty is the standard limited warranty.</p>","zh":"<p>提供黑、白两款的低跨点休闲电动自行车。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。骑行前调整坐垫，检查刹车、轮胎及电池固定状态。所列赠品为车锁，随附一年保修属于标准有限保修。</p>"}', pic='/cbjj/products/10/main.png', images='["/cbjj/products/10/main.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Model","value":"U2"},{"label":"Frame","value":"Step-through"},{"label":"Colors","value":"Black / White"}],"zh":[{"label":"型号","value":"U2"},{"label":"车架","value":"低跨点"},{"label":"颜色","value":"黑色 / 白色"}]}', specs='{"en":[{"label":"Model","value":"U2","icon":"ZapIcon"},{"label":"Frame","value":"Step-through","icon":"ZapIcon"},{"label":"Colors","value":"Black / White","icon":"ZapIcon"}],"zh":[{"label":"型号","value":"U2","icon":"ZapIcon"},{"label":"车架","value":"低跨点","icon":"ZapIcon"},{"label":"颜色","value":"黑色 / 白色","icon":"ZapIcon"}]}', quick_know='{"en":["A step-through cruiser bike available in black or white.","Adjust the saddle and check the brakes, tires and battery attachment before riding. The listed gift is a bike lock; the included one-year warranty is the standard limited warranty.","Only in-stock variants are sold."],"zh":["提供黑、白两款的低跨点休闲电动自行车。","骑行前调整坐垫，检查刹车、轮胎及电池固定状态。所列赠品为车锁，随附一年保修属于标准有限保修。","仅销售有库存的所选版本。"]}', box_items='{"en":["Bike body","Charger","Toolkit","Manual","Bike lock"],"zh":["自行车主体","适配充电器","工具包","使用说明书","车锁"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer