UPDATE pms_product SET slug='cbjj-long-range-3-wheel-kids-electric-scooter', name='{"en":"CBJJ Mini Three-Wheel Kids Electric Scooter","zh":"CBJJ Mini 儿童三轮电动滑板车"}', subtitle='{"en":"A three-wheel kids scooter offered in blue, pink and two-unit packs.","zh":"提供蓝色、粉色及双台组合的儿童三轮滑板车。"}', description='{"en":"<p>A three-wheel kids scooter offered in blue, pink and two-unit packs.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Use only under adult supervision in a closed, dry area away from traffic. Choose the child’s fit according to the supplied manual; wear a helmet and protective pads.</p>","zh":"<p>提供蓝色、粉色及双台组合的儿童三轮滑板车。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。仅在成人监护下，于远离交通的干燥封闭场地使用。按随附说明书确认儿童身高与使用适配，佩戴头盔及护具。</p>"}', pic='/cbjj/products/11/main.png', images='["/cbjj/products/11/main.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Model","value":"Mini"},{"label":"Wheels","value":"3"},{"label":"Colors","value":"Blue / Pink"},{"label":"Pack","value":"1 / 2"}],"zh":[{"label":"型号","value":"Mini"},{"label":"车轮数量","value":"3"},{"label":"颜色","value":"蓝色 / 粉色"},{"label":"组合数量","value":"1 / 2"}]}', specs='{"en":[{"label":"Model","value":"Mini","icon":"ZapIcon"},{"label":"Wheels","value":"3","icon":"ZapIcon"},{"label":"Colors","value":"Blue / Pink","icon":"ZapIcon"},{"label":"Pack","value":"1 / 2","icon":"ZapIcon"}],"zh":[{"label":"型号","value":"Mini","icon":"ZapIcon"},{"label":"车轮数量","value":"3","icon":"ZapIcon"},{"label":"颜色","value":"蓝色 / 粉色","icon":"ZapIcon"},{"label":"组合数量","value":"1 / 2","icon":"ZapIcon"}]}', quick_know='{"en":["A three-wheel kids scooter offered in blue, pink and two-unit packs.","Use only under adult supervision in a closed, dry area away from traffic. Choose the child’s fit according to the supplied manual; wear a helmet and protective pads.","Only in-stock variants are sold."],"zh":["提供蓝色、粉色及双台组合的儿童三轮滑板车。","仅在成人监护下，于远离交通的干燥封闭场地使用。按随附说明书确认儿童身高与使用适配，佩戴头盔及护具。","仅销售有库存的所选版本。"]}', box_items='{"en":["Scooter body","Charger","Toolkit","Manual","Standard accessories are supplied for each scooter in a two-unit pack.","Gift packaging when the gift-box option is selected."],"zh":["滑板车主体","适配充电器","工具包","使用说明书","双台组合包含每台车对应的标准配件。","选择礼盒选项时包含礼盒包装。"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Use only under adult supervision in a closed, dry area away from traffic. Choose the child’s fit according to the supplied manual; wear a helmet and protective pads."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"仅在成人监护下，于远离交通的干燥封闭场地使用。按随附说明书确认儿童身高与使用适配，佩戴头盔及护具。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[],"zh":[]}' WHERE id=11;

