UPDATE pms_product SET slug='cbjj-gt2-off-road-electric-scooter-peak-1000w', name='{"en":"CBJJ GT2 1000W Off Road Electric Scooter — 2026 Edition","zh":"CBJJ GT2 1000W 越野电动滑板车 · 2026 版"}', subtitle='{"en":"The GT2 2026 off-road model, with standard and seated options.","zh":"GT2 2026 越野款，提供标准版与带座版本。"}', description='{"en":"<p>The GT2 2026 off-road model, with standard and seated options.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Select GT2 Standard or GT2 with Seat; both listed options include a scooter bag. Check the seat fasteners when fitted and verify local road restrictions before use.</p>","zh":"<p>GT2 2026 越野款，提供标准版与带座版本。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。选择 GT2 标准版或带座版，现有两种选项均包含滑板车包。带座版须检查座椅紧固件，并在使用前核对当地道路规定。</p>"}', pic='/cbjj/products/12/main.png', images='["/cbjj/products/12/main.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Model","value":"GT2"},{"label":"Motor","value":"1000W"},{"label":"Version","value":"2026"},{"label":"Options","value":"Standard / With Seat"}],"zh":[{"label":"型号","value":"GT2"},{"label":"电机","value":"1000W"},{"label":"版本","value":"2026"},{"label":"可选配置","value":"标准版 / 带座版"}]}', specs='{"en":[{"label":"Model","value":"GT2","icon":"ZapIcon"},{"label":"Motor","value":"1000W","icon":"ZapIcon"},{"label":"Version","value":"2026","icon":"ZapIcon"},{"label":"Options","value":"Standard / With Seat","icon":"ZapIcon"}],"zh":[{"label":"型号","value":"GT2","icon":"ZapIcon"},{"label":"电机","value":"1000W","icon":"ZapIcon"},{"label":"版本","value":"2026","icon":"ZapIcon"},{"label":"可选配置","value":"标准版 / 带座版","icon":"ZapIcon"}]}', quick_know='{"en":["The GT2 2026 off-road model, with standard and seated options.","Select GT2 Standard or GT2 with Seat; both listed options include a scooter bag. Check the seat fasteners when fitted and verify local road restrictions before use.","Only in-stock variants are sold."],"zh":["GT2 2026 越野款，提供标准版与带座版本。","选择 GT2 标准版或带座版，现有两种选项均包含滑板车包。带座版须检查座椅紧固件，并在使用前核对当地道路规定。","仅销售有库存的所选版本。"]}', box_items='{"en":["Scooter body","Charger","Toolkit","Manual","Scooter bag (both variants)","Seat assembly (seated variant only)"],"zh":["滑板车主体","适配充电器","工具包","使用说明书","滑板车包（两种版本均含）","座椅组件（仅带座版）"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Select GT2 Standard or GT2 with Seat; both listed options include a scooter bag. Check the seat fasteners when fitted and verify local road restrictions before use."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"选择 GT2 标准版或带座版，现有两种选项均包含滑板车包。带座版须检查座椅紧固件，并在使用前核对当地道路规定。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[],"zh":[]}' WHERE id=12;

