UPDATE pms_product SET slug='s-nova-commuting-electric-scooter', name='{"en":"CBJJ S Nova Commuting Electric Scooter","zh":"CBJJ S Nova 通勤电动滑板车"}', subtitle='{"en":"A commuter scooter with 8.5-inch tires and a 600W peak catalog motor.","zh":"现有商品参数标注 8.5 英寸轮胎、600W 峰值电机的通勤滑板车。"}', description='{"en":"<p>A commuter scooter with 8.5-inch tires and a 600W peak catalog motor.</p><p>Catalog parameters describe the base version. Range and speed vary with conditions; check local road rules. Check the lights, brakes and tires before departure. The listed 600W figure is peak motor power, not a promise of continuous output; use the supplied compatible charger.</p>","zh":"<p>现有商品参数标注 8.5 英寸轮胎、600W 峰值电机的通勤滑板车。</p><p>参数描述基础版；续航及速度受使用条件影响，请核对当地道路规定。出发前检查灯光、刹车和轮胎。600W 为所列电机峰值功率，不代表持续输出承诺；使用随附的适配充电器。</p>"}', pic='/cbjj/products/15/main.png', images='["/cbjj/products/15/main.png"]', app_image='', tags='{"en":[],"zh":[]}', spec_table='{"en":[{"label":"Motor","value":"600W peak"},{"label":"Range","value":"Up to 19 miles"},{"label":"Top Speed","value":"20 MPH"},{"label":"Tires","value":"8.5 inch pneumatic"},{"label":"Load Capacity","value":"264 lbs"},{"label":"Climbing Ability","value":"15% grade"}],"zh":[{"label":"电机","value":"600W 峰值"},{"label":"续航（估算）","value":"最高约 19 英里"},{"label":"最高速度（估算）","value":"20 英里/小时"},{"label":"轮胎","value":"8.5 英寸充气轮胎"},{"label":"载重","value":"264 磅"},{"label":"爬坡能力","value":"15% 坡度"}]}', specs='{"en":[{"label":"Motor","value":"600W peak","icon":"ZapIcon"},{"label":"Range","value":"Up to 19 miles","icon":"ZapIcon"},{"label":"Top Speed","value":"20 MPH","icon":"ZapIcon"},{"label":"Tires","value":"8.5 inch pneumatic","icon":"ZapIcon"}],"zh":[{"label":"电机","value":"600W 峰值","icon":"ZapIcon"},{"label":"续航（估算）","value":"最高约 19 英里","icon":"ZapIcon"},{"label":"最高速度（估算）","value":"20 英里/小时","icon":"ZapIcon"},{"label":"轮胎","value":"8.5 英寸充气轮胎","icon":"ZapIcon"}]}', quick_know='{"en":["A commuter scooter with 8.5-inch tires and a 600W peak catalog motor.","Check the lights, brakes and tires before departure. The listed 600W figure is peak motor power, not a promise of continuous output; use the supplied compatible charger.","Only in-stock variants are sold."],"zh":["现有商品参数标注 8.5 英寸轮胎、600W 峰值电机的通勤滑板车。","出发前检查灯光、刹车和轮胎。600W 为所列电机峰值功率，不代表持续输出承诺；使用随附的适配充电器。","仅销售有库存的所选版本。"]}', box_items='{"en":["Scooter body","Charger","Toolkit","User manual"],"zh":["滑板车主体","适配充电器","工具包","使用说明书"]}', faqs='{"en":[{"question":"Is this item available for preorder?","answer":"No. Only variants showing available stock can be ordered; unavailable options cannot be purchased."},{"question":"What should I check before ordering?","answer":"Check the lights, brakes and tires before departure. The listed 600W figure is peak motor power, not a promise of continuous output; use the supplied compatible charger."},{"question":"What delivery and after-sales policies apply?","answer":"Dispatch in 1–3 business days. Free standard delivery: US/Canada 5–10 business days, mainland China 3–7. Request returns within 30 days of delivery; one-year limited warranty. See the full policies for conditions."},{"question":"Are the images inventory or certification evidence?","answer":"No. Generated illustrations are used only to demonstrate products; they are not stock, procurement or certification evidence."}],"zh":[{"question":"可以预订缺货款吗？","answer":"不可以。仅售现货，只有显示可用库存的版本才能下单。"},{"question":"购买前应核对什么？","answer":"出发前检查灯光、刹车和轮胎。600W 为所列电机峰值功率，不代表持续输出承诺；使用随附的适配充电器。"},{"question":"适用哪些配送与售后政策？","answer":"1–3 个工作日发货，标准配送免运费。美国/加拿大预计运输 5–10 个工作日，中国大陆 3–7 个工作日。签收后 30 天内可申请退货，提供一年有限保修，具体条件请查看完整政策。"},{"question":"图片可用作库存或认证证明吗？","answer":"不可以。生成图片仅用于商品展示，不作为库存、进货或认证证据。"}]}', upsells='{"en":[{"code":"cable-lock","name":"CBJJ Cable Lock","description":"Steel cable parking lock. Confirm mounting and reach before purchase.","price":29.99,"compareAtPrice":39.99,"image":"/cbjj/products/7/main.png"},{"code":"warranty-1y","name":"1-Year Extended Limited Warranty","description":"Adds 1 year(s) after the included one-year limited warranty. The same defect coverage and exclusions apply; statutory rights remain unaffected.","price":69.99,"compareAtPrice":89.99,"image":"/cbjj/hero/hero.png"}],"zh":[{"code":"cable-lock","name":"CBJJ 钢缆锁","description":"用于停车固定的钢缆锁，购买前请核对固定方式及长度适配。","price":29.99,"compareAtPrice":39.99,"image":"/cbjj/products/7/main.png"},{"code":"warranty-1y","name":"1 年延长有限保修","description":"在随附的一年有限保修结束后延长 1 年，适用相同的缺陷保障和除外条款，不影响法定权利。","price":69.99,"compareAtPrice":89.99,"image":"/cbjj/hero/hero.png"}]}' WHERE id=15;

